  if (kind === "task-addition") return optional + " completionCriteria \u4E3A\u6807\u51C6\u6570\u7EC4\uFF0CallowedPaths \u4E3A\u975E\u7A7A\u76F8\u5BF9\u8DEF\u5F84\u6570\u7EC4\uFF0CinScope \u4E3A\u5E03\u5C14\u503C\uFF0CscopeReason \u8BF4\u660E\u8303\u56F4\u5224\u65AD\u3002\u4E0D\u81EA\u884C\u6267\u884C\u4EFB\u52A1\u3002";
